  static AbilityDefinition Ability(string name,float damage,float cost,float range,float windup,float recovery,float radius,Color tint){string p=Root+"/Definitions/"+name.Replace(' ','-')+".asset";var a=AssetDatabase.LoadAssetAtPath<AbilityDefinition>(p);if(!a){a=ScriptableObject.CreateInstance<AbilityDefinition>();AssetDatabase.CreateAsset(a,p);}a.title=name;a.damage=damage;a.cost=cost;a.range=range;a.windup=windup;a.recovery=recovery;a.radius=radius;a.tint=tint;EditorUtility.SetDirty(a);return a;}
  static ItemDefinition Item(string id,string title,string detail,Color c){string p=Root+"/Definitions/"+id+".asset";var a=AssetDatabase.LoadAssetAtPath<ItemDefinition>(p);if(!a){a=ScriptableObject.CreateInstance<ItemDefinition>();AssetDatabase.CreateAsset(a,p);}a.stableId=id;a.title=title;a.description=detail;a.tint=c;a.consumable=id=="food";EditorUtility.SetDirty(a);return a;}
  static float RouteX(float z)=>z<35?z*.2f:z<80?7+Mathf.Sin((z-35)*.055f)*8:z<120?12-(z-80)*.25f:2;
  static void Environment(){TerrainGround();for(int i=0;i<64;i++){float z=-25+i*3.1f;float x=RouteX(Mathf.Max(0,z));var road=Shape("Ancient road",PrimitiveType.Cylinder,new Vector3(x,.025f,z),new Vector3(z<20?11:7,.035f,6),z>82?ash:path,null,false);road.transform.rotation=Quaternion.Euler(0,Rand(-12,12),0);}for(int i=0;i<70;i++){float z=Rand(-30,178),side=i%2==0?-1:1;float x=side*Rand(38,70);var rock=Rock(new Vector3(x,Rand(0,2),z),Rand(10,22));rock.name="Valley escarpment";}for(int i=0;i<170;i++){float z=Rand(-28,175);float x=Rand(-65,65);if(Mathf.Abs(x-RouteX(z))<10||z<23&&Mathf.Abs(x)<27||z>115&&Mathf.Abs(x)<22)continue;Tree(new Vector3(x,0,z),Rand(.8f,1.8f));}for(int i=0;i<120;i++){float z=Rand(-25,115),x=Rand(-42,42);if(Mathf.Abs(x-RouteX(z))<5||z<20&&Mathf.Abs(x)<24)continue;Rock(new Vector3(x,.2f,z),Rand(.6f,2.1f));}Cube("Stillwater creek",new Vector3(-30,.04f,55),new Vector3(7,.07f,170),water,null,false);for(int i=0;i<28;i++)Rock(new Vector3(-26+Rand(-1,1),0,-20+i*6),Rand(1,2.5f));}
  static void TerrainGround(){var data=new TerrainData();data.heightmapResolution=257;data.size=new Vector3(160,18,230);var heights=new float[257,257];for(int z=0;z<257;z++)for(int x=0;x<257;x++){float wx=-80+x/256f*160,wz=-48+z/256f*230;float edge=Mathf.SmoothStep(0,1,Mathf.InverseLerp(32,70,Mathf.Abs(wx-RouteX(Mathf.Max(0,wz)))));heights[z,x]=(1+edge*(3+Mathf.PerlinNoise(wx*.035f+100,wz*.035f+100)*8))/18;}data.SetHeights(0,0,heights);var layers=new TerrainLayer[3];Color[] colors={new Color(.22f,.31f,.22f),new Color(.32f,.31f,.23f),new Color(.25f,.23f,.28f)};for(int l=0;l<3;l++){var tex=new Texture2D(64,64);for(int y=0;y<64;y++)for(int x=0;x<64;x++)tex.SetPixel(x,y,colors[l]*Rand(.88f,1.12f));tex.Apply();AssetDatabase.CreateAsset(tex,Root+"/Materials/Ground-"+l+".asset");layers[l]=new TerrainLayer();layers[l].diffuseTexture=tex;layers[l].tileSize=new Vector2(7,7);AssetDatabase.CreateAsset(layers[l],Root+"/Materials/GroundLayer-"+l+".terrainlayer");}data.terrainLayers=layers;data.alphamapResolution=256;var alpha=new float[256,256,3];for(int z=0;z<256;z++)for(int x=0;x<256;x++){float wz=-48+z/255f*230;float ashBlend=Mathf.SmoothStep(0,1,Mathf.InverseLerp(70,116,wz));float dirt=Mathf.PerlinNoise(x*.06f,z*.06f)*.4f;alpha[z,x,0]=(1-ashBlend)*(1-dirt);alpha[z,x,1]=(1-ashBlend)*dirt;alpha[z,x,2]=ashBlend;}data.SetAlphamaps(0,0,alpha);AssetDatabase.CreateAsset(data,Root+"/ValleyTerrain.asset");var ground=Terrain.CreateTerrainGameObject(data);ground.name="Authored valley terrain";ground.transform.SetParent(sceneRoot.transform);ground.transform.position=new Vector3(-80,-1,-48);var terrain=ground.GetComponent<Terrain>();terrain.materialTemplate=new Material(Shader.Find("Universal Render Pipeline/Terrain/Lit"));AssetDatabase.CreateAsset(terrain.materialTemplate,Root+"/Materials/Terrain.mat");terrain.heightmapPixelError=8;}
  static void Tree(Vector3 p,float scale){p.y+=Mathf.SmoothStep(0,1,Mathf.InverseLerp(32,70,Mathf.Abs(p.x-RouteX(Mathf.Max(0,p.z)))))*(3+Mathf.PerlinNoise(p.x*.035f+100,p.z*.035f+100)*8);var g=Group("Whisper cedar",p);Shape("Trunk",PrimitiveType.Cylinder,new Vector3(0,2*scale,0),new Vector3(.65f*scale,2*scale,.65f*scale),trunk,g.transform);for(int k=0;k<3;k++){var crown=Shape("Cedar crown",PrimitiveType.Sphere,new Vector3(Rand(-.4f,.4f),4*scale+k*1.25f*scale,0),new Vector3((4-k*.7f)*scale,2.5f*scale,(4-k*.7f)*scale),leaf,g.transform,false);crown.transform.localRotation=Quaternion.Euler(Rand(-10,10),Rand(0,180),Rand(-10,10));}}
  static void Settlement(){Shape("Cinderhollow square",PrimitiveType.Cylinder,new Vector3(0,.035f,0),new Vector3(35,.04f,32),path,null,false);Building("hearth","Hearth House",new Vector3(-11,0,0),"A roof, a hearth, a name. Elian's home anchors his return.");Building("forge","Mira's Forge",new Vector3(12,0,4),"The forge is Mira's duty; her lost hammer is her identity.");Building("garden","Community Garden",new Vector3(-10,0,16),"A shared garden returns food, color, and a reason to gather.");Building("beacon","Dawn Beacon",new Vector3(12,0,18),"Restore the smith, then kindle the freed Dawn Ember.");Soul("Elian",new Vector3(-5,0,-4),"hearth");Soul("Mira",new Vector3(7,0,5),"forge");Soul("Sera",new Vector3(-6,0,13),"garden");for(int i=0;i<7;i++){float a=i*Mathf.PI*2/7;Rock(new Vector3(Mathf.Cos(a)*1.4f,.15f,Mathf.Sin(a)*1.4f),.7f);}Shape("Hearth ember",PrimitiveType.Sphere,new Vector3(0,.45f,0),new Vector3(.8f,.8f,.8f),gold,null,false);LightAt(new Vector3(0,2,0),new Color(1,.5f,.17f),9,2);Sign(new Vector3(5,0,24),"EAST ROAD\nWhisperwood ? Sanctuary");
   int id=0;for(int i=0;i<14;i++){float a=i*2.39996f;float r=22+(i%3)*5;var p=new Vector3(Mathf.Cos(a)*r,0,Mathf.Sin(a)*r+3);Resource("wood-"+id++,"Fallen heartwood",p,"wood",3);if(i%2==0)Resource("stone-"+id++,"Salvage stone",p+new Vector3(3,0,2),"stone",3);}for(int i=0;i<5;i++){Resource("food-"+i,"Wildfruit bush",new Vector3(-18-i*2,0,24+i*5),"food",3);Resource("iron-"+i,"Bog iron",new Vector3(21+i,0,27+i*7),"iron",2);}}
  static void Building(string id,string title,Vector3 p,string detail){var root=Group(title,p);root.AddComponent<BoxCollider>().size=new Vector3(7,2,6);root.GetComponent<BoxCollider>().center=Vector3.up;var interaction=root.AddComponent<WorldInteractable>();interaction.Configure(id,title,InteractionKind.Building,detail);interactions.Add(interaction);var a=Group("Ruined",Vector3.zero,root.transform);var b=Group("Stabilized",Vector3.zero,root.transform);var c=Group("Restored",Vector3.zero,root.transform);interaction.Visuals(a,b,c);
   foreach(var stage in new[]{a,b,c}){int index=stage==a?0:stage==b?1:2;var t=stage.transform;Cube("Original foundation",new Vector3(0,.2f,0),new Vector3(7,.4f,6),stone,t);if(id=="garden"){for(int row=0;row<3;row++){Cube("Raised planting bed",new Vector3(-2+row*2,.5f,0),new Vector3(1.3f,.55f,4.7f),wood,t);if(index>0)for(int j=0;j<5;j++)Shape("New growth",PrimitiveType.Sphere,new Vector3(-2+row*2,.9f,-1.7f+j*.8f),Vector3.one*(index==2?.7f:.3f),index==2?leaf:grass,t,false);}if(index==2){Cube("Garden bench",new Vector3(0,.8f,-3.5f),new Vector3(4,.3f,.7f),wood,t);LightAt(new Vector3(0,2,0),new Color(1,.7f,.3f),7,1,t);}continue;}if(id=="beacon"){Shape("Remembered plinth",PrimitiveType.Cylinder,new Vector3(0,.8f,0),new Vector3(3,.7f,3),stone,t);Shape("Beacon pillar",PrimitiveType.Cylinder,new Vector3(0,index==0?1.5f:3,0),new Vector3(1,index==0?.5f:2,1),index==2?plaster:stone,t);if(index>0)Shape("Brazier",PrimitiveType.Sphere,new Vector3(0,5,0),new Vector3(2,.5f,2),iron,t);if(index==2){Shape("Dawn flame",PrimitiveType.Sphere,new Vector3(0,5.8f,0),new Vector3(1.3f,2,1.3f),gold,t,false);LightAt(new Vector3(0,6,0),new Color(1,.67f,.27f),28,5,t);}continue;}
    Cube("Rear wall",new Vector3(0,index==0?1:2,2.75f),new Vector3(7,index==0?1.5f:3.7f,.35f),index==2?plaster:stone,t);for(int side=-1;side<=1;side+=2){Cube("Side wall",new Vector3(side*3.3f,index==0?.9f:2,0),new Vector3(.35f,index==0?1.2f:3.7f,5.5f),index==2?plaster:stone,t);if(index>0)Cube("Oak upright",new Vector3(side*3.3f,2,-2.7f),new Vector3(.35f,4,.35f),wood,t);}if(index>0){for(int side=-1;side<=1;side+=2){var r=Cube("Gabled roof",new Vector3(side*1.8f,4.45f,0),new Vector3(4.1f,.25f,6.7f),index==2?roof:wood,t);r.transform.localRotation=Quaternion.Euler(0,0,-side*23);}Cube("Roof ridge",new Vector3(0,5.2f,0),new Vector3(.3f,.3f,6.8f),wood,t);}else for(int j=0;j<5;j++){var beam=Cube("Collapsed oak",new Vector3(Rand(-2,2),.6f,Rand(-2,2)),new Vector3(.25f,.25f,4),wood,t);beam.transform.localRotation=Quaternion.Euler(0,Rand(0,180),Rand(-12,12));}
    if(index==2){Cube("Welcome step",new Vector3(0,.3f,-3.2f),new Vector3(2,.35f,1),stone,t);LightAt(new Vector3(0,2,-1),new Color(1,.6f,.25f),9,2,t);Cube("Service table",new Vector3(0,1.1f,1),new Vector3(3,.3f,1.4f),wood,t);if(id=="forge"){Cube("Anvil",new Vector3(0,1.5f,-1),new Vector3(1.6f,.6f,.7f),iron,t);Cube("Forge coals",new Vector3(-2,.8f,1),new Vector3(1,.3f,1),gold,t);}else{Cube("Woven rug",new Vector3(0,.43f,0),new Vector3(3,.04f,3),roof,t);Cube("Bed",new Vector3(-2,.8f,1),new Vector3(1.4f,.6f,2.3f),wood,t);}}}
   PrefabUtility.SaveAsPrefabAsset(root,Root+"/Prefabs/"+id+".prefab");}
  static void LightAt(Vector3 p,Color color,float range,float intensity,Transform t=null){var g=Group("Warm lantern",p,t);var l=g.AddComponent<Light>();l.type=LightType.Point;l.color=color;l.range=range;l.intensity=intensity;}
  static Character Actor(string id,string name,Vector3 p,bool hostile,float hp,Color color,float scale){var g=Group(name,p);g.transform.localScale=Vector3.one*scale;var capsule=g.AddComponent<CapsuleCollider>();capsule.height=2;capsule.center=Vector3.up;capsule.radius=.4f;var actor=g.AddComponent<Character>();actor.Configure(id,name,hostile?Allegiance.Hostile:Allegiance.Friendly,hp);var mat=Mat("Cloth-"+id,color);var body=Group("Articulated figure",Vector3.zero,g.transform);Shape("Tunic",PrimitiveType.Capsule,new Vector3(0,1.1f,0),new Vector3(.8f,.65f,.5f),mat,body.transform,false);Shape("Head",PrimitiveType.Sphere,new Vector3(0,1.88f,0),Vector3.one*.48f,hostile?dark:plaster,body.transform,false);var left=Cube("Left boot",new Vector3(-.19f,.4f,0),new Vector3(.27f,.75f,.35f),dark,body.transform,false);var right=Cube("Right boot",new Vector3(.19f,.4f,0),new Vector3(.27f,.75f,.35f),dark,body.transform,false);Cube("Cloak",new Vector3(0,1.1f,-.3f),new Vector3(.85f,1.2f,.1f),hostile?corrupt:roof,body.transform,false);var sword=Group("Blade grip",new Vector3(.6f,1.3f,.1f),body.transform);Cube("Blade",new Vector3(0,.5f,0),new Vector3(.11f,1.15f,.2f),iron,sword.transform,false);Cube("Guard",Vector3.zero,new Vector3(.5f,.1f,.15f),gold,sword.transform,false);g.AddComponent<ActorPresentation>().Configure(body.transform,sword.transform,left.transform,right.transform,color);g.AddComponent<Combatant>();return actor;}
  static void Soul(string name,Vector3 p,string building){var root=Group(name+" : identity anchor",p);root.AddComponent<SphereCollider>().radius=1.5f;root.GetComponent<SphereCollider>().center=Vector3.up;root.GetComponent<SphereCollider>().isTrigger=true;var i=root.AddComponent<WorldInteractable>();i.Configure("soul-"+building,name+"'s soul",InteractionKind.Soul);interactions.Add(i);var wisp=Shape("Wisp",PrimitiveType.Sphere,new Vector3(0,1.5f,0),Vector3.one*.55f,gold,root.transform,false);LightAt(new Vector3(0,1.4f,0),new Color(1,.55f,.2f),5,1.5f,wisp.transform);var spectre=Shape("Spectre",PrimitiveType.Capsule,new Vector3(0,1.2f,0),new Vector3(.65f,1,.65f),gold,root.transform,false);var person=Actor("resident-"+building,name,Vector3.zero,false,80,new Color(.6f,.4f,.25f),1).gameObject;person.transform.SetParent(root.transform,false);var presentation=root.AddComponent<SoulPresentation>();presentation.Configure(building,wisp,spectre,person);souls.Add(presentation);}
  static void Resource(string id,string title,Vector3 p,string item,int quantity){var g=Group(title,p);var interaction=g.AddComponent<WorldInteractable>();interaction.Configure(id,title,InteractionKind.Resource,"",item,quantity);interactions.Add(interaction);if(item=="wood"){var log=Shape("Fallen log",PrimitiveType.Cylinder,new Vector3(0,.45f,0),new Vector3(.8f,1.7f,.8f),wood,g.transform);log.transform.localRotation=Quaternion.Euler(0,0,85);Shape("Cut end",PrimitiveType.Cylinder,new Vector3(1.67f,.58f,0),new Vector3(.72f,.03f,.72f),plaster,g.transform).transform.localRotation=Quaternion.Euler(0,0,85);}else if(item=="food"){Shape("Berry bush",PrimitiveType.Sphere,new Vector3(0,.7f,0),new Vector3(1.9f,1.4f,1.8f),leaf,g.transform);for(int j=0;j<5;j++)Shape("Wildfruit",PrimitiveType.Sphere,new Vector3(Rand(-.7f,.7f),Rand(.8f,1.4f),Rand(-.7f,.7f)),Vector3.one*.22f,roof,g.transform,false);}else{Rock(new Vector3(0,.5f,0),1.5f,g.transform);if(item=="iron")for(int j=0;j<4;j++)Cube("Iron vein",new Vector3(Rand(-.4f,.4f),.9f,Rand(-.4f,.4f)),new Vector3(.25f,.4f,.3f),iron,g.transform,false);}Shape("Gather glint",PrimitiveType.Sphere,new Vector3(0,1.6f,0),Vector3.one*.13f,gold,g.transform,false);}
  static void Sign(Vector3 p,string text){var g=Group("Wayfinding",p);Cube("Signpost",new Vector3(0,1.2f,0),new Vector3(.18f,2.4f,.18f),wood,g.transform);Cube("Carved board",new Vector3(0,2.1f,0),new Vector3(3,.85f,.14f),dark,g.transform);var label=Group("Inscription",new Vector3(0,2.2f,-.09f),g.transform);var tm=label.AddComponent<TextMesh>();tm.text=text;tm.characterSize=.16f;tm.fontSize=36;tm.anchor=TextAnchor.MiddleCenter;tm.alignment=TextAlignment.Center;tm.color=new Color(1,.82f,.5f);label.transform.localRotation=Quaternion.identity;}
  static void SpawnEnemy(string id,string name,Vector3 p,bool ranged=false,bool boss=false){var c=Actor(id,name,p,true,boss?420:ranged?60:75,boss?new Color(.37f,.2f,.4f):ranged?new Color(.5f,.25f,.4f):new Color(.37f,.37f,.31f),boss?1.7f:1);var agent=c.gameObject.AddComponent<NavMeshAgent>();agent.radius=boss?.7f:.4f;agent.height=2;agent.angularSpeed=360;agent.acceleration=12;c.GetComponent<Combatant>().Configure(ranged?bolt:bite,boss?slam:bite);var brain=c.gameObject.AddComponent<EnemyBrain>();brain.Configure(boss,ranged);enemies.Add(brain);c.gameObject.AddComponent<AttackTelegraph>();PrefabUtility.SaveAsPrefabAsset(c.gameObject,Root+"/Prefabs/"+(boss?"Ash-Warden":ranged?"Cinder-Seer":"Ashbound")+".prefab");}
  static void Forest(){for(int i=0;i<10;i++){float z=35+i*4;float x=RouteX(z);if(i%2==0)Tree(new Vector3(x+7,0,z),1.3f);else Tree(new Vector3(x-7,0,z),1.3f);}Sign(new Vector3(12,0,54),"THE WHISPERWOOD\nBeyond: the Ashen Approach");SpawnEnemy("road-1","Ashbound sentinel",new Vector3(16,.1f,61));SpawnEnemy("road-2","Cinder seer",new Vector3(21,.1f,78),true);SpawnEnemy("road-3","Ashbound sentinel",new Vector3(9,.1f,91));for(int i=0;i<5;i++){float z=75+i*6;Cube("Broken pilgrim wall",new Vector3(RouteX(z)-6,.7f,z),new Vector3(1,1.4f,3),stone);}for(int i=0;i<4;i++){float z=49+i*14;Resource("trail-food-"+i,"Wildfruit bush",new Vector3(RouteX(z)-6,0,z),"food",3);}Sign(new Vector3(8,0,105),"SUNKEN SANCTUARY\nThe dragon's echo waits within");}
  static void Sanctuary(){Cube("Sanctuary floor",new Vector3(2,.08f,143),new Vector3(37,.16f,64),dark);for(int side=-1;side<=1;side+=2){Cube("Sanctuary curtain wall",new Vector3(2+side*19,3.5f,143),new Vector3(1.8f,7,65),stone);for(int z=117;z<173;z+=10){Shape("Old colonnade",PrimitiveType.Cylinder,new Vector3(2+side*13,3,z),new Vector3(1.5f,3,1.5f),plaster);Cube("Pillar capital",new Vector3(2+side*13,6,z),new Vector3(2.5f,.6f,2.5f),stone);}}Cube("Sanctuary apse",new Vector3(2,4,175),new Vector3(39,8,2),stone);for(int side=-1;side<=1;side+=2){Cube("Entrance pier",new Vector3(2+side*5,4,112),new Vector3(2,8,3),plaster);}Cube("Sanctuary lintel",new Vector3(2,8,112),new Vector3(14,2,3),stone);for(int z=118;z<170;z+=7)Cube("Pilgrim inlay",new Vector3(2,.18f,z),new Vector3(3,.08f,3),path,null,false);Cube("Shattered screen left",new Vector3(-9,1.4f,135),new Vector3(14,2.8f,1.4f),stone);Cube("Shattered screen right",new Vector3(14,1.4f,144),new Vector3(12,2.8f,1.4f),stone);for(int i=0;i<8;i++){Rock(new Vector3(i%2==0?-12:16,.3f,120+i*6),Rand(1,2));LightAt(new Vector3(i%2==0?-13:17,3,119+i*7),new Color(.45f,.35f,.8f),9,.7f);}SpawnEnemy("sanctuary-1","Oathless guardian",new Vector3(-4,.3f,124));SpawnEnemy("sanctuary-2","Cinder seer",new Vector3(10,.3f,132),true);SpawnEnemy("sanctuary-3","Oathless guardian",new Vector3(3,.3f,145));SpawnEnemy("warden","Ash Warden",new Vector3(2,.3f,164),false,true);Shape("The broken sun mosaic",PrimitiveType.Cylinder,new Vector3(2,.2f,164),new Vector3(18,.05f,18),path,null,false);var gate=Group("Cleansed waystone",new Vector3(11,0,169));Shape("Waystone",PrimitiveType.Cylinder,new Vector3(0,1.6f,0),new Vector3(1.5f,1.6f,1.5f),gold,gate.transform);var interaction=gate.AddComponent<WorldInteractable>();interaction.Configure("return-gate","Waystone : Return to Cinderhollow",InteractionKind.ReturnGate);interactions.Add(interaction);LightAt(new Vector3(2,6,165),new Color(.8f,.3f,.3f),24,2);}
  [MenuItem("Rekindle/Build Windows")]public static void BuildWindows(){try{if(File.Exists("Artifacts/managed-build.request")){File.Delete("Artifacts/managed-build.request");PrototypeBuildSettings.Apply();if(!File.ReadAllText("Artifacts/windows-optimization-profile.txt").StartsWith("Windows prototype:"))throw new InvalidOperationException("Windows optimization profile could not be applied");}Directory.CreateDirectory("Builds/Windows");var result=BuildPipeline.BuildPlayer(EditorBuildSettings.scenes,"Builds/Windows/Rekindle.exe",BuildTarget.StandaloneWindows64,BuildOptions.None);File.WriteAllText("Artifacts/build-result.txt",result.summary.result+"; errors="+result.summary.totalErrors+"; warnings="+result.summary.totalWarnings+"; bytes="+result.summary.totalSize);}catch(Exception e){File.WriteAllText("Artifacts/build-result.txt",e.ToString());Debug.LogException(e);}}
 }
